// TestPostCommit_ActiveSession_SkipsSentinelWait is a regression test verifying that
// PostCommit for an ACTIVE session with AgentType=ClaudeCode and a TranscriptPath
// completes quickly without hitting the 3s sentinel timeout in PrepareTranscript.
//
// Before the fix, ACTIVE sessions always hit the full 3s timeout in
// waitForTranscriptFlush because the stop sentinel can never appear while
// the agent is still running.
//
// After the fix, PrepareTranscript is skipped entirely for ACTIVE sessions.
func TestPostCommit_ActiveSession_SkipsSentinelWait(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-active-skip-sentinel"

	// Initialize session and save a checkpoint
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	// Set phase to ACTIVE, set AgentType to Claude Code, and set TranscriptPath.
	// Without these, the PrepareTranscript code path is never reached.
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	state.AgentType = agent.AgentTypeClaudeCode

	// Create a recent transcript file (no sentinel) — before the fix this would
	// trigger waitForTranscriptFlush which polls for 3s and times out.
	transcriptFile := filepath.Join(dir, ".entire", "transcript-"+sessionID+".jsonl")
	require.NoError(t, os.MkdirAll(filepath.Dir(transcriptFile), 0o755))
	require.NoError(t, os.WriteFile(transcriptFile, []byte(`{"type":"human"}`+"\n"), 0o644))
	state.TranscriptPath = transcriptFile

	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Create a commit WITH the Entire-Checkpoint trailer
	commitWithCheckpointTrailer(t, repo, dir, "b1b2b3b4b5b6")

	// Time PostCommit — before the fix this would take ~3s+ due to sentinel timeout
	start := time.Now()
	err = s.PostCommit(context.Background())
	elapsed := time.Since(start)
	require.NoError(t, err)

	// Assert it completes well under the 3s sentinel timeout.
	assert.Less(t, elapsed, 2*time.Second,
		"ACTIVE session PostCommit should skip sentinel wait and complete in <2s, took %v", elapsed)

	// Verify condensation still happened correctly
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")
	assert.NotNil(t, sessionsRef)
}

